se_qs, urlencode, urlunparse\\n\\nclass UrlListBuilder:\\n    def __init__(\\n        self,\\n        base_url: str = \\"\\",\\n        page_param: str = \\"page\\",\\n        page_start: int = 1,\\n        page_end: int = 1,\\n        manual_urls: str = \\"\\",\\n    ):\\n        self.base_url = base_url\\n        self.page_param = page_param\\n        self.page_start = page_start\\n        self.page_end = page_end\\n        self.manual_urls = manual_urls\\n\\n    def build(self) -> dict:\\n        # \\u624b\\u52d5\\u30ea\\u30b9\\u30c8\\u304c\\u6e21\\u3055\\u308c\\u3066\\u3044\\u308c\\u3070\\u3001\\u305d\\u3061\\u3089\\u3092\\u512a\\u5148\\u3057\\u3066\\u305d\\u306e\\u307e\\u307e\\u4f7f\\u3046\\n        if self.manual_urls.strip():\\n            urls = [\\n                line.strip()\\n                for line in self.manual_urls.splitlines()\\n                if line.strip()\\n            ]\\n            return {\\"urls\\": urls}\\n\\n        # \\u624b\\u52d5\\u30ea\\u30b9\\u30c8\\u304c\\u7121\\u3051\\u308c\\u3070\\u5f93\\u6765\\u901a\\u308abase_url\\u304b\\u3089\\u81ea\\u52d5\\u751f\\u6210\\n        if not self.base_url:\\n            return {\\"urls\\": []}\\n\\n        parsed = urlparse(self.base_url)\\n        query_dict = parse_qs(parsed.query)\\n\\n        urls = []\\n        for i in range(self.page_start, self.page_end + 1):\\n            query_dict[self.page_param] = [i]\\n            new_query = urlencode(query_dict, doseq=True)\\n            new_url = urlunparse(\\n                (parsed.scheme, parsed.netloc, parsed.path, parsed.params, new_query, parsed.fragment)\\n            )\\n            urls.append(new_url)\\n\\n        return {\\"urls\\": urls}\\n\\n\\ndef main(\\n    base_url: str = \\"\\",\\n    page_param: str = \\"page\\",\\n    page_start: int = 1,\\n    page_end: int = 1,\\n    manual_urls: str = \\"\\",\\n) -> dict:\\n    url_builder = UrlListBuilder(\\n        base_url=base_url,\\n        page_param=page_param,\\n        page_start=page_start,\\n        page_end=page_end,\\n        manual_urls=manual_urls,\\n    )\\n    return url_builder.build()", "code_language": "python3", "outputs": {"urls": {"children": null, "type": "array[string]"}}, "selected": false, "title": "\\u30b3\\u30fc\\u30c9\\u5b9f\\u884c\\uff08URLs\\uff09", "type": "code", "variables": [{"value_selector": ["1785476883085", "base_url"], "value_type": "string", "variable": "base_url"}, {"value_selector": ["1785476883085", "page_param"], "value_type": "string", "variable": "page_param"}, {"value_selector": ["1785476883085", "page_start"], "value_type": "number", "variable": "page_start"}, {"value_selector": ["1785476883085", "page_end"], "value_type": "number", "variable": "page_end"}]}, "height": 51, "id": "1785476682482", "position": {"x": 143.61001596557287, "y": 256.4842834334896}, "positionAbsolute": {"x": 143.61001596557287, "y": 256.4842834334896}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 242}, {"data": {"error_handle_mode": "terminated", "flatten_output": true, "height": 312, "is_parallel": false, "iterator_input_type": "array[string]", "iterator_selector": ["1785476682482", "urls"], "output_selector": ["1785490482139", "body"], "output_type": "array[string]", "parallel_nums": 10, "selected": false, "start_node_id": "1785490476300start", "title": "\\u30a4\\u30c6\\u30ec\\u30fc\\u30b7\\u30e7\\u30f3\\uff08\\u30b9\\u30af\\u30ec\\u30a4\\u30d4\\u30f3\\u30b0\\uff09", "type": "iteration", "width": 988}, "height": 312, "id": "1785490476300", "position": {"x": 449.01293937380933, "y": 258}, "positionAbsolute": {"x": 449.01293937380933, "y": 258}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 988, "zIndex": 1}, {"data": {"desc": "", "isInIteration": true, "selected": false, "title": "", "type": "iteration-start"}, "draggable": false, "height": 48, "id": "1785490476300start", "parentId": "1785490476300", "position": {"x": 24, 