u7d5e\\u308a\\u8fbc\\u3080\\n    matched = [item for item in items if item.get(\\"name\\") == dataset_name]\\n\\n    if not matched:\\n        raise ValueError(f\\"\\u30ca\\u30ec\\u30c3\\u30b8\\u30d9\\u30fc\\u30b9\\u304c\\u898b\\u3064\\u304b\\u308a\\u307e\\u305b\\u3093: {dataset_name}\\")\\n\\n    return {\\"dataset_id\\": matched[0][\\"id\\"]}", "code_language": "python3", "outputs": {"dataset_id": {"children": null, "type": "string"}}, "selected": false, "title": "\\u30b3\\u30fc\\u30c9\\u5b9f\\u884c\\uff08database_id\\uff09", "type": "code", "variables": [{"value_selector": ["1785476883085", "dataset_name"], "value_type": "string", "variable": "dataset_name"}, {"value_selector": ["1785476883085", "dataset_api_key"], "value_type": "string", "variable": "dataset_api_key"}]}, "height": 51, "id": "1785743036109", "position": {"x": -178.762278875111, "y": 258}, "positionAbsolute": {"x": -178.762278875111, "y": 258}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 242}, {"data": {"code": "import requests\\n\\ndef main(dataset_id: str = \\"\\", api_base: str = \\"http://dify-api:5001/v1\\", dataset_api_key: str = \\"\\") -> dict:\\n    headers = {\\"Authorization\\": f\\"Bearer {dataset_api_key}\\"}\\n    deleted_count = 0\\n    page = 1\\n\\n    while True:\\n        resp = requests.get(\\n            f\\"{api_base}/datasets/{dataset_id}/documents\\",\\n            headers=headers,\\n            params={\\"page\\": page, \\"limit\\": 100},\\n            timeout=10,\\n        )\\n        resp.raise_for_status()\\n        data = resp.json()\\n        documents = data.get(\\"data\\", [])\\n\\n        if not documents:\\n            break\\n\\n        for doc in documents:\\n            del_resp = requests.delete(\\n                f\\"{api_base}/datasets/{dataset_id}/documents/{doc['id']}\\",\\n                headers=headers,\\n                timeout=10,\\n            )\\n            if del_resp.ok:\\n                deleted_count += 1\\n\\n        if not data.get(\\"has_more\\"):\\n            break\\n        page += 1\\n\\n    return {\\"deleted_count\\": deleted_count}", "code_language": "python3", "outputs": {"deleted_count": {"children": null, "type": "number"}}, "selected": false, "title": "\\u30b3\\u30fc\\u30c9\\u5b9f\\u884c\\uff08Delete RAG\\uff09", "type": "code", "variables": [{"value_selector": ["1785743036109", "dataset_id"], "value_type": "string", "variable": "dataset_id"}, {"value_selector": ["1785476883085", "dataset_api_key"], "value_type": "string", "variable": "dataset_api_key"}]}, "height": 51, "id": "1785745282756", "position": {"x": 143.61001596557287, "y": 368.64730935525915}, "positionAbsolute": {"x": 143.61001596557287, "y": 368.64730935525915}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 242}, {"data": {"code": "import json\\n\\ndef main(body: str) -> dict:\\n    try:\\n        data = json.loads(body)\\n        markdown = data.get(\\"data\\", {}).get(\\"markdown\\", \\"\\")\\n    except (json.JSONDecodeError, AttributeError):\\n        markdown = \\"\\"\\n\\n    return {\\"content\\": markdown}\\n", "code_language": "python3", "isInIteration": true, "isInLoop": false, "iteration_id": "1785490476300", "outputs": {"content": {"children": null, "type": "string"}}, "selected": false, "title": "\\u30b3\\u30fc\\u30c9\\u5b9f\\u884c\\uff08\\u30d9\\u30af\\u30c8\\u30eb\\u30c7\\u30fc\\u30bf\\u5909\\u63db\\uff09", "type": "code", "variables": [{"value_selector": ["1785490482139", "body"], "value_type": "string", "variable": "body"}]}, "height": 51, "id": "1785746094411", "parentId": "1785490476300", "position": {"x": 414.35855090140626, "y": 65}, "positionAbsolute": {"x": 863.3714902752156, "y": 323}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 242, "zIndex": 1002}, {"data": {"authorization": {"config": null, "type": "no-auth"}, "body": {"data": [{"id": "key-v