  def build(self) -> dict:\\n        if not self.base_url:\\n            return {\\"urls\\": []}\\n\\n        parsed = urlparse(self.base_url)\\n        query_dict = parse_qs(parsed.query)\\n\\n        separator = \\"&\\" if \\"?\\" in self.base_url else \\"?\\"\\n        urls = []\\n        for i in range(self.page_start, self.page_end + 1):\\n            query_dict[self.page_param] = [i]\\n            new_query = urlencode(query_dict, doseq=True)\\n            new_url = urlunparse(\\n                (\\n                    parsed.scheme,\\n                    parsed.netloc,\\n                    parsed.path,\\n                    parsed.params,\\n                    new_query,\\n                    parsed.fragment,\\n                )\\n            )\\n            urls.append(new_url)\\n\\n        return {\\"urls\\": urls}\\n\\n\\ndef main(\\n    base_url: str = \\"\\",\\n    page_param: str = \\"page\\",\\n    page_start: int = 1,\\n    page_end: int = 1,\\n) -> dict:\\n    url_builder = UrlListBuilder(\\n        base_url=base_url,\\n        page_param=page_param,\\n        page_start=page_start,\\n        page_end=page_end,\\n    )\\n    return url_builder.build()\\n", "code_language": "python3", "outputs": {"urls": {"children": null, "type": "array[string]"}}, "selected": false, "title": "\\u30b3\\u30fc\\u30c9\\u5b9f\\u884c\\uff08URLs\\uff09", "type": "code", "variables": []}, "height": 51, "id": "1785476682482", "position": {"x": 145.12573253208313, "y": 258}, "positionAbsolute": {"x": 145.12573253208313, "y": 258}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 242}, {"data": {"authorization": {"config": null, "type": "no-auth"}, "body": {"data": [{"id": "key-value-109", "key": "", "type": "text", "value": "{\\n  \\"name\\": \\"{{#sys.timestamp#}}_{{#1785490476300.output#}}\\",\\n  \\"text\\": \\"{{#1785485710500.content#}}\\",\\n  \\"indexing_technique\\": \\"high_quality\\",\\n\\u00a0 \\"process_rule\\": {