self.page_end = page_end\\n\\n    def build(self) -> dict:\\n        if not self.base_url:\\n            return {\\"urls\\": []}\\n\\n        parsed = urlparse(self.base_url)\\n        query_dict = parse_qs(parsed.query)\\n\\n        urls = []\\n        for i in range(self.page_start, self.page_end + 1):\\n            query_dict[self.page_param] = [i]\\n            new_query = urlencode(query_dict, doseq=True)\\n            new_url = urlunparse(\\n                (\\n                    parsed.scheme,\\n                    parsed.netloc,\\n                    parsed.path,\\n                    parsed.params,\\n                    new_query,\\n                    parsed.fragment,\\n                )\\n            )\\n            urls.append(new_url)\\n\\n        return {\\"urls\\": urls}\\n\\n\\ndef main(\\n    base_url: str = \\"\\",\\n    page_param: str = \\"page\\",\\n    page_start: int = 1,\\n    page_end: int = 1,\\n) -> dict:\\n    url_builder = UrlListBuilder(\\n        base_url=base_url,\\n        page_param=page_param,\\n        page_start=page_start,\\n        page_end=page_end,\\n    )\\n    return url_builder.build()", "code_language": "python3", "outputs": {"urls": {"children": null, "type": "array[string]"}}, "selected": false, "title": "\\u30b3\\u30fc\\u30c9\\u5b9f\\u884c\\uff08URLs\\uff09", "type": "code", "variables": [{"variable": "base_url", "value_selector": ["1785476883085", "base_url"], "value_type": "string"}, {"variable": "page_param", "value_selector": ["1785476883085", "page_param"], "value_type": "string"}, {"variable": "page_start", "value_selector": ["1785476883085", "page_start"], "value_type": "number"}, {"variable": "page_end", "value_selector": ["1785476883085", "page_end"], "value_type": "number"}]}, "height": 51, "id": "1785476682482", "position": {"x": 148.1571656651039, "y": 258}, "positionAbsolute": {"x": 148.1571656651039, "y": 258}, "selected": true, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "widt