"}], "outputs": {"dataset_id": {"type": "string", "children": null}}, "type": "code", "title": "\\u30b3\\u30fc\\u30c9\\u5b9f\\u884c\\uff08database_id\\uff09", "selected": false}, "position": {"x": -178.762278875111, "y": 258}, "targetPosition": "left", "sourcePosition": "right", "positionAbsolute": {"x": -178.762278875111, "y": 258}, "width": 242, "height": 51, "selected": false}, {"id": "1785745282756", "type": "custom", "data": {"code": "import requests\\n\\ndef main(dataset_id: str = \\"\\", api_base: str = \\"http://api:5001/v1\\", dataset_api_key: str = \\"\\") -> dict:\\n    headers = {\\"Authorization\\": f\\"Bearer {dataset_api_key}\\"}\\n    deleted_count = 0\\n    page = 1\\n\\n    while True:\\n        resp = requests.get(\\n            f\\"{api_base}/datasets/{dataset_id}/documents\\",\\n            headers=headers,\\n            params={\\"page\\": page, \\"limit\\": 100},\\n            timeout=10,\\n        )\\n        resp.raise_for_status()\\n        data = resp.json()\\n        documents = data.get(\\"data\\", [])\\n\\n        if not documents:\\n            break\\n\\n        for doc in documents:\\n            del_resp = requests.delete(\\n                f\\"{api_base}/datasets/{dataset_id}/documents/{doc['id']}\\",\\n                headers=headers,\\n                timeout=10,\\n            )\\n            if del_resp.ok:\\n                deleted_count += 1\\n\\n        if not data.get(\\"has_more\\"):\\n            break\\n        page += 1\\n\\n    return {\\"deleted_count\\": deleted_count}", "code_language": "python3", "variables": [{"variable": "dataset_id", "value_selector": ["1785743036109", "dataset_id"], "value_type": "string"}, {"variable": "dataset_api_key", "value_selector": ["1785476883085", "dataset_api_key"], "value_type": "string"}], "outputs": {"deleted_count": {"type": "number", "children": null}}, "type": "code", "title": "\\u30b3\\u30fc\\u30c9\\u5b9f\\u884c\\uff08Delete RAG\\uff09", "selected": false}, "position": {"x": 14